import React, {useId, useLayoutEffect, useRef, useState} from 'react';
import './search.css';
export type FilterToken = {id: string; label: string; expression: string};
export type SearchValue = {tokens: FilterToken[]; text: string};
export type Suggestion = {id: string; label: string; token: FilterToken};
type Props = {value: SearchValue; onChange: (value: SearchValue) => void; suggestions: Suggestion[]; onSearch: () => void; onQueryChange: (text: string) => void};
// Parsing, suggestion generation and committed search state belong to the application.
export function TokenSearch({value, onChange, suggestions, onSearch, onQueryChange}: Props) {
 const id = useId(); const input = useRef<HTMLInputElement>(null); const pendingCaret = useRef<number | null>(null); const [editing, setEditing] = useState<string | null>(null); const [draft, setDraft] = useState(''); const [active, setActive] = useState(-1); const [expanded, setExpanded] = useState(false); const [announcement, announce] = useState(''); const text = editing ? draft : value.text;
 useLayoutEffect(() => {if (pendingCaret.current !== null && input.current) {input.current.focus(); const caret = Math.min(pendingCaret.current, input.current.value.length); input.current.setSelectionRange(caret, caret); pendingCaret.current = null;}}, [value, draft, editing]);
 function restore(caret: number) {pendingCaret.current = caret;}
 function remove(token: FilterToken) {restore(input.current?.selectionStart ?? value.text.length); onChange({...value, tokens: value.tokens.filter(t => t.id !== token.id)}); if (editing === token.id) {setEditing(null); setDraft('');} announce(`Removed ${token.label}`);}
 function beginEdit(token: FilterToken) {setEditing(token.id); setDraft(token.expression); restore(token.expression.length); onQueryChange(token.expression); setExpanded(true); setActive(-1);}
 function choose(suggestion: Suggestion) {const tokens = editing ? value.tokens.map(token => token.id === editing ? {...suggestion.token, id: token.id} : token) : [...value.tokens, suggestion.token]; onChange({tokens, text: editing ? value.text : ''}); restore(editing ? value.text.length : 0); setEditing(null); setDraft(''); setExpanded(false); setActive(-1); onQueryChange(''); announce(`${editing ? 'Replaced filter with' : 'Added filter'} ${suggestion.label}`);}
 return <div className="token-search" role="search" aria-label="Workspace search"><label htmlFor={`${id}-input`}>Search workspace</label><div className="search-editor"><ol aria-label="Applied filters">{value.tokens.map(token => <li key={token.id}><button type="button" onClick={() => beginEdit(token)} aria-label={`Edit filter ${token.label}`}>{token.label}</button><button type="button" aria-label={`Remove filter ${token.label}`} onClick={() => remove(token)}>×</button></li>)}</ol><input id={`${id}-input`} ref={input} type="text" role="combobox" aria-autocomplete="list" aria-expanded={expanded && suggestions.length > 0} aria-controls={`${id}-suggestions`} aria-activedescendant={expanded && active >= 0 && suggestions[active] ? `${id}-option-${active}` : undefined} aria-describedby={`${id}-help`} value={text} onFocus={() => setExpanded(true)} onBlur={event => {if (!event.currentTarget.parentElement?.parentElement?.contains(event.relatedTarget as Node)) setExpanded(false);}} onChange={event => {const next = event.target.value; if (editing) setDraft(next); else onChange({...value, text: next}); onQueryChange(next); setExpanded(true); setActive(-1);}} onKeyDown={event => {if (event.nativeEvent.isComposing) return; if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {event.preventDefault(); setExpanded(true); setActive(current => suggestions.length ? (current + (event.key === 'ArrowDown' ? 1 : -1) + suggestions.length) % suggestions.length : -1);} else if (event.key === 'Enter') {event.preventDefault(); if (expanded && suggestions[active]) choose(suggestions[active]); else if (!editing) onSearch();} else if (event.key === 'Escape') {setExpanded(false); setActive(-1); if (editing) {setEditing(null); restore(value.text.length); onQueryChange(value.text); announce('Filter editing cancelled');}} else if (event.key === 'Backspace' && !text && !editing && value.tokens.length) {event.preventDefault(); beginEdit(value.tokens[value.tokens.length - 1]);}}}/><button type="button" onClick={() => {onChange({tokens: [], text: ''}); setEditing(null); setDraft(''); restore(0); setExpanded(false); onQueryChange(''); announce('Search cleared');}}>Clear search</button><button type="button" disabled={!!editing} onClick={onSearch}>Search</button></div><p id={`${id}-help`}>{editing ? 'Editing filter. Choose a suggestion to replace it; Escape cancels.' : 'Type to search. Use arrow keys and Enter for suggestions. Edit or remove filters with their buttons.'}</p><ul id={`${id}-suggestions`} role="listbox" aria-label="Filter suggestions" hidden={!expanded || suggestions.length === 0}>{suggestions.map((suggestion, index) => <li key={suggestion.id} id={`${id}-option-${index}`} role="option" aria-selected={active === index} onMouseDown={event => event.preventDefault()} onClick={() => choose(suggestion)}>{suggestion.label}</li>)}</ul><span className="search-sr" role="status">{announcement}</span></div>;
}
